#  Academic Radiology: ≤5,000단어, 참고 ≤50, 표 ≤5, 그림 ≤10, 구조 초록 250(Rationale and Objectives·Materials and Methods·Results·Conclusion), Take-Home Messages 1–2(각 ≤50단어), 키워드 3–5, 짧은 제목 ≤6단어, 이중 익명.
from numbers_ches import load, ROB, BL, PA, FAC, UPT, HYP
N = load()
def ci(v, src=None):
    r = (src or N["main"])[v]; return f"RR {r['IRR']:.3f}; 95% CrI {r['lo']:.3f}–{r['hi']:.3f}"
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {t[1]:.3f}–{t[2]:.3f}"
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["nco"][(o, v)]
SC = lambda s, v: N["sens_main"][s][v]
WI = lambda v, w: N["win_irr"][(v, w)]
PH = lambda s, v: N["ph_extra"][(s, v)]
EN = {"전라남도": "South Jeolla", "경상북도": "North Gyeongsang", "경상남도": "South Gyeongsang", "충청남도": "South Chungcheong", "전라북도": "North Jeolla",
      "강원도": "Gangwon", "부산시": "Busan", "충청북도": "North Chungcheong", "대구시": "Daegu", "경기도": "Gyeonggi", "서울시": "Seoul", "인천시": "Incheon",
      "광주시": "Gwangju", "울산시": "Ulsan", "대전시": "Daejeon", "세종시": "Sejong", "제주도": "Jeju"}
def sidos(d, n):
    l = [f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + " and " + l[-1]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
TITLE = "Where is a screening chest radiograph called abnormal? District variation in other chest disease flags over 14 years of Korean national health screening"
RUNNING = "District variation in chest radiograph flags"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower() and len(RUNNING.split()) <= 6
KEYWORDS = ["Mass screening", "Radiography, thoracic", "Quality assurance, health care", "Spatio-temporal analysis", "Republic of Korea"]
assert 3 <= len(KEYWORDS) <= 5
NHYP = N["n_hyp"]; assert NHYP == 11
SUP = {"methods": 1, "covariates": 2, "checks": 3, "maps": 4, "windows": 5, "specs": 6, "posthoc": 7, "strobe": 8}
def sup(k): return f"Supplementary Appendix S{SUP[k]}"
_pc = lambda v: f"{100*N['mv'][v]['cred_frac']:.0f}%"
ALT = N["retention"]; D = N["desc"]
BEST = min(KH, key=lambda a: N["s43_waic"][a]); assert BEST == "KH_typeI"
nat = N["nat_pos_y"]; NR = N["rate"]; VP = {k: v["share_of_linear_predictor_var"] for k, v in N["varpart"].items()}
NULL_EXPO = ["ext__tb_history_share", "current_smoking_rate", "factory_land_share", "coal_plant_host"]
NULL_OTHER = [UPT, "ext__clinics_per100k", "walking_practice_rate"]

TAKE_HOME = [
 f"Across {N['n_districts']} Korean districts and {N['exam_total']/1e6:.0f} million screening examinations, the sex- and age-standardised share of chest radiographs flagged as other chest disease varied 1.9-fold between the 10th and 90th percentile districts, with a spatially structured pattern that persisted over 14 years.",
 "District markers of tuberculosis history, smoking, industrial land and coal-fired power plants did not account for this geography; differences in reading and reporting, examinee composition and unmeasured disease remain possible explanations and warrant facility-level audit.",
]
assert len(TAKE_HOME) == 2 and all(len(t.split()) <= 50 for t in TAKE_HOME)

ABSTRACT = {
 "Rationale and Objectives": "Chest radiography is part of Korea's national general health screening, and the share of radiographs flagged as other chest disease is published for every district. This study described the geography of this flag and examined whether district markers of chronic lung disease and occupational exposure were associated with it.",
 "Materials and Methods": f"Ecological panel study of {N['exam_total']/1e6:.0f} million screening examinations in {N['n_districts']} districts, 2011–2024, with expected numbers standardised for sex and age. Negative binomial Bayesian spatiotemporal models related standardised ratios to {NHYP} district characteristics (tuberculosis history, smoking, industrial land, coal-fired power plants, deprivation, screening uptake, clinic density, physical activity), with covariate-subset, space–time and negative-control analyses.",
 "Results": f"Of all examinations, {N['cases_total']/1e6:.1f} million ({100*N['cases_total']/N['exam_total']:.1f}%) were flagged. Standardised ratios ranged from {D['sir_min']:.2f} to {D['sir_max']:.2f} (10th–90th percentile {D['sir_p10']:.2f}–{D['sir_p90']:.2f}), were spatially clustered (annual Moran's I {N['moran_year_min']:.2f}–{N['moran_year_max']:.2f}) and persistent (Kendall's W {N['kendall_W']:.2f}). Tuberculosis history, industrial land and coal-fired power plants were not associated; smoking was inversely associated only in space–time models. Basic livelihood security receipt was inversely associated (rate ratio per standard deviation {M[BL]['IRR']:.2f}; 95% credible interval {M[BL]['lo']:.2f}–{M[BL]['hi']:.2f}); a decomposition attributed this to change within districts over time. Positive associations with physical activity, contrary to expectation, were not retained in two of four space–time models.",
 "Conclusion": "Flags for other chest disease at Korean health screening vary persistently between districts and are not explained by the district exposure markers examined. Before district flag rates are used to compare areas or plan services, facility-level audit should examine how far reading and reporting practices, examinee composition and unmeasured disease contribute.",
}

INTRO = [
 f"Chest radiographs taken for screening often show findings that are not suspicious for cancer: in a large screening trial, such abnormalities were reported on about a third of examinations, most often granulomas, scarring or fibrosis, cardiac abnormalities and pleural fibrosis [@pinsky2006abnormalities]. In asymptomatic adults, routine chest radiography has a low yield of important disease [@tigges2004routine; @eisenberg2010low]. Reporting also depends on the reader; in screening radiographs from a lung cancer trial, readers differed widely in how often they reported noncalcified nodules, with only fair agreement [@singh2012reader].",
 f"Korea's National Health Insurance Service offers a general health examination that includes a chest radiograph to adults [@seong2017cohort]. The programme classifies each radiograph as normal, suspected pulmonary tuberculosis or suspected other chest disease, and the national statistics portal publishes the number of examinees flagged in each category for every district and year [@web:kosis2026screening]. Korean health screening centres read large volumes of radiographs with a low prevalence of clinically significant lesions, which has motivated work on artificial intelligence (AI) triage of normal radiographs [@yoo2022artificial; @kim2021performance; @kim2023multicentre]. In Korea's national lung cancer screening programme with low-dose computed tomography (CT), positive rates varied widely between radiologists and institutions [@hwang2021variability]; how far flag rates in the much larger chest radiograph programme vary between areas is not known, although such variation would matter for quality assurance and for any future AI-assisted triage.",
 f"Several district exposures could plausibly raise the rate of abnormal chest radiographs. Radiologic changes of healed tuberculosis are common in Korean adults and are associated with airflow obstruction [@hwang2014association; @choi2017definition], and tuberculosis notification in Korea remains concentrated in older adults [@lee2025tuberculosis]. Smoking, occupational dust and fumes [@murgia2022occupational; @torn2017occupational; @lam2012past; @grahn2021occupational], pneumoconiosis among former dust-exposed workers [@lee2011development; @chong2006pneumoconiosis] and air pollution, including that near coal-fired power plants [@hii2022respiratory; @lee2025assessing], are associated with chronic lung disease, and interstitial lung abnormalities are common at CT screening [@grantorser2023prevalence; @chae2023interstitial; @jin2024interstitial], although their visibility on radiographs is limited. Neighbourhood deprivation is associated with lung function decline and emphysema [@thatipelli2022neighborhood], whereas regular physical activity is associated with slower lung function decline in smokers [@garciaaymerich2007regular]. If the district geography of the flag follows markers of these exposures, it is more likely to describe disease; if not, examinee composition, unmeasured disease and the way radiographs are read and reported are all candidate explanations.",
 f"This study used 14 years of national screening statistics to describe where in Korea chest radiographs are flagged as other chest disease more often than expected for the sex and age of examinees, how stable that geography is, and whether district markers of chest exposures, deprivation, screening selection, clinic density and physical activity are associated with it.",
]

METHODS = [
("Design, outcome and population",
 f"This ecological panel study used annual district statistics of the general health examination of the National Health Insurance Service [@seong2017cohort]. For each district and year, the number of examinees with a recorded judgement and the number flagged as suspected other chest disease on the chest radiograph were taken by sex from the national statistics portal, as were national numbers by sex and age group [@web:kosis2026screening]. This category is separate from suspected pulmonary tuberculosis; the statistics assign examinees to districts but do not give the radiologic finding, the reader or the screening facility. Districts were harmonised to 2024 boundaries. Sejong, published only as a province row with figures by sex for every year, was linked as a single district, giving {N['n_districts']} districts and {N['n_rows']:,} district-years for 2011–2024 with no missing outcome; district sums equalled national totals in every year ({sup('methods')}). The outcome was chosen from the published screening judgements because its district pattern showed spatial clustering and persistence after adjustment for urbanisation in a screening of candidate outcomes; the study is therefore exploratory, and the strength of the spatial pattern is not an independent finding."),
("Sex and age standardisation",
 "Expected numbers were obtained by indirect standardisation [@inskip1983methods]. National positivity in each year, sex and age group (19 years or younger, 5-year groups from 20–24 to 80–84 years, and 85 years or older) was applied to the estimated age structure of each district's examinees, derived from the resident population by sex and 5-year age group [@web:mois2026population] and national uptake by sex and age, and rescaled to the observed number of examinees of each sex. The standardised ratio is the observed over the expected number. Using national positivity of the same year accounts for nationwide changes in positivity but not for changes that differ between districts."),
("District characteristics",
 "Characteristics and expected directions were fixed before any covariate model was fitted. Chest exposures: the share of examinees classified by the programme as already under treatment for pulmonary tuberculosis on the basis of the screening questionnaire, as a marker of tuberculosis history independent of the radiograph reading (+) [@hwang2014association; @choi2017definition]; current smoking from the Community Health Survey [@kang2015korea] (+); the share of district area registered as factory sites, as a marker of occupational dust and fumes (+) [@murgia2022occupational]; and the presence of a coal-fired power plant in operation during the study period (+) [@hii2022respiratory]. Deprivation: basic livelihood security receipt (+) [@thatipelli2022neighborhood] and tertiary education (−). Screening selection and reading: screening uptake (−, with healthier people attending where uptake is high [@froom1999healthy]) and clinics per 100,000 population (no direction fixed, as a marker of the share of examinations read in small clinics). Physical activity: walking, moderate-or-vigorous physical activity (−) [@garciaaymerich2007regular] and public sports facilities per 100,000 population (−). Five controls were forced into every model: urban population share, physicians per 1,000 population, sex ratio, fiscal autonomy and the share aged 80 years or older. Covariates were standardised to 1 standard deviation (SD); gaps were filled within districts, and 33 implausible 2021–2023 values of basic livelihood security receipt (below 20% or above five times the 2020 and 2024 mean) were set to missing and interpolated (" + sup("covariates") + "; checks in " + sup("checks") + ")."),
("Statistical analysis",
 f"The likelihood was chosen by the lower widely applicable information criterion (WAIC) of the forced-controls model. Models had an offset of log expected numbers, a Besag–York–Mollié 2 (BYM2) district effect on a 593-edge contact graph with penalised-complexity priors (precision: P(σ > 0.5) = 0.01; mixing: P(φ < 0.5) = 2/3) [@riebler2016intuitive; @simpson2017penalising], first-order random-walk and independent year effects with the same precision prior, and Gaussian priors with precision 4 for the standardised coefficients, and were fitted by integrated nested Laplace approximation [@rue2009approximate] in R 4.6.0 [@web:rcore2026]. Rate ratios (RRs) per 1 SD are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1. RRs are mutually adjusted ecological associations, not individual or causal effects [@morgenstern1995ecologic; @greenland1989ecological]. Adapting the multiverse approach [@steegen2016increasing], the model was refitted with 200 random covariate subsets; a covariate was subset-stable if credible in at least 75% of the subsets containing it, with the same sign in at least 95%. The exponentiated BYM2 effect gives a residual district relative risk; hot and cold spots had a posterior probability above 0.95 or below 0.05 that it exceeded 1, for the whole period and for 2011–2015, 2016–2019 and 2020–2024. The share of linear-predictor variance due to each model component and the share of district variance in log standardised ratios between provinces were computed."),
("Sensitivity and post hoc analyses",
 f"The principal model and its covariates were specified in advance; Knorr-Held type I–IV space–time interactions were added as sensitivity analyses [@knorrheld2000bayesian], noting that type I, an independent district-year effect, absorbs unstructured overdispersion; covariates were split into district means and within-district deviations [@bell2015explaining]; the model was refitted in each window; and expected numbers were recomputed from the resident population. The 2024 data were predicted from the model fitted to the other years with 2024 covariates, and calibration was assessed with posterior predictive intervals and the probability integral transform. Further specifications varied the likelihood, priors, neighbourhoods, controls, lags, left-out provinces or years, filled values and province-by-year random effects ({sup('specs')}). Respiratory and gastric cancer deaths served as comparison outcomes and hit-and-run accidents, fires and household waste recycling as negative-control exposures [@lipsitch2010negative]; E-values were computed [@vanderweele2017sensitivity]. After the results were seen, three characteristics fixed in advance for sensitivity analysis only were added singly and together: the share of examinees flagged as suspected pulmonary tuberculosis, a second judgement from the same radiograph reading and so a marker of local reading thresholds; the share of households in detached houses; and internal medicine specialists per 100,000. Prompted by the 2021–2023 correction, the principal model was also refitted without 2021–2023. The residual district relative risks of seven districts with former major coal mines were compared with those of other districts ({sup('posthoc')})."),
("Ethics and reporting",
 "The study used only published aggregate statistics and involved no individual data. The Institutional Review Board of [blinded] approved the study on 4 November 2025 ([blinded]) and its continuing review on 3 November 2026 ([blinded]) and waived informed consent, and the study was conducted in accordance with the Declaration of Helsinki. Reporting follows the STROBE statement [@vonelm2007strengthening] (" + sup("strobe") + ")."),
]

_e = lambda k: tuple(N['negctl'][k][x] for x in ('IRR', 'lo', 'hi'))
RESULTS = [
("Screening and positivity",
 f"Over 2011–2024, {N['exam_total']/1e6:.1f} million examinations included {N['cases_total']:,} flagged as suspected other chest disease ({100*N['cases_total']/N['exam_total']:.2f}%; Table 1). National positivity was {nat[2011]:.2f}% in 2011, {nat[2019]:.2f}% in 2019, {min(nat.values()):.2f}% in 2021 and {nat[2024]:.2f}% in 2024. Positivity rose steeply with age, from {NR[(2024, '남자', '20-24')]:.1f}% in men and {NR[(2024, '여자', '20-24')]:.1f}% in women aged 20–24 years to {NR[(2024, '남자', '85+')]:.1f}% and {NR[(2024, '여자', '85+')]:.1f}% at 85 years or older in 2024 (Fig. 1)."),
("Spatial pattern",
 f"District standardised ratios over the whole period ranged from {D['sir_min']:.2f} to {D['sir_max']:.2f}, with a 10th–90th percentile range of {D['sir_p10']:.2f}–{D['sir_p90']:.2f}. Moran's I was {N['moran_year_min']:.2f}–{N['moran_year_max']:.2f} annually; the BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f}–{N['phi'][2]:.2f}), and the structured spatial effect accounted for {100*VP['spatial_structured']:.0f}% of linear-predictor variance, the unstructured district effect {100*VP['spatial_unstructured']:.0f}%, all covariates together {100*VP['fixed_covariates']:.0f}% and year effects {100*VP['year_effects']:.0f}% (shares do not sum to 100% because components covary). Residual district relative risks ranged from {N['rr_min']:.2f} to {N['rr_max']:.2f}, with {N['n_hot']} hot spots, mainly in {sidos(N['hot_by_sido'], 3)}, and {N['n_cold']} cold spots, mainly in {sidos(N['cold_by_sido'], 3)} (Fig. 2A). In all three windows, {N['hot_all_windows']} districts were hot spots and {N['cold_all_windows']} cold spots (Fig. 2B). District rankings were stable (Kendall's W {N['kendall_W']:.2f}; median Spearman's ρ between adjacent years {D['rho_year_adjacent_median']:.2f}), although ρ between 2011 and 2024 was {D['rho_2011_2024']:.2f}. Provinces accounted for {100*D['share_var_between_sido']:.0f}% of the district variance in log standardised ratios ({sup('maps')})."),
("District characteristics",
 f"The negative binomial likelihood was selected (WAIC {N['waic_nb']:,.1f} vs {N['waic_pois']:,.1f}). Adding the {NHYP} characteristics changed WAIC from {N['waic_forced']:,.1f} to {N['waic_main']:,.1f}; residual Moran's I was {N['moran_resid']:.2f}. Credible intervals included 1 for tuberculosis history among examinees ({ci('ext__tb_history_share')}), smoking ({ci('current_smoking_rate')}), industrial land ({ci('factory_land_share')}) and coal-fired power plants ({ci('coal_plant_host')}), and for screening uptake, clinic density and walking (Table 2; Fig. 3). In window-specific models, coal-fired power plants were credible in 2011–2015 ({tci(WI('coal_plant_host', 'W1_2011-15'))}) and smoking was inversely associated in that window ({tci(WI('current_smoking_rate', 'W1_2011-15'))}). Without any district effect, tuberculosis history ({tci(S43('no_spatial', 'ext__tb_history_share'))}) and coal-fired power plants ({tci(S43('no_spatial', 'coal_plant_host'))}) were positively associated, but with an independent district effect alone their intervals included 1 ({tci(S43('iid_only', 'ext__tb_history_share'))} and {tci(S43('iid_only', 'coal_plant_host'))}). Four characteristics were credible and three were subset-stable. Standardised ratios were lower with more basic livelihood security receipt ({ci(BL)}; subset-stable in {_pc(BL)} of subsets) and with more tertiary education ({ci('tertiary_educated_share')}; {_pc('tertiary_educated_share')}), and higher with more moderate-or-vigorous physical activity ({ci(PA)}; {_pc(PA)}) and more public sports facilities ({ci(FAC)}; {_pc(FAC)}). Apart from tertiary education, these associations ran against the expected direction. Of the negative-control exposures, fires were associated ({tci(_e('fires_per_10000'))}), whereas hit-and-run accidents and recycling were not."),
("Space–time models and sensitivity analyses",
 f"All four interaction types fitted better than the principal model (ΔWAIC {dW('KH_typeIII'):,.0f} to {dW('KH_typeI'):,.0f}); type I, which absorbs unstructured district-year overdispersion, had the lowest WAIC and type II the lowest among structured interactions. Basic livelihood security receipt remained credible in all four types (type II {tci(S43('KH_typeII', BL))}; type IV {tci(S43('KH_typeIV', BL))}). Physical activity and sports facilities remained credible in type I but not in types II or IV (type II {tci(S43('KH_typeII', PA))} and {tci(S43('KH_typeII', FAC))}); smoking became inversely associated in types II–IV (type II {tci(S43('KH_typeII', 'current_smoking_rate'))}) (Table 2). Across the {ALT[BL]['n_specs']} alternative specifications in the first block of Supplementary Table S6, basic livelihood security receipt was credible in {ALT[BL]['kept']}, physical activity in {ALT[PA]['kept']} and sports facilities in {ALT[FAC]['kept']} ({sup('specs')}). Adding province-by-year random effects lowered WAIC by {N['waic_main'] - N['s41_waic']['C4_sido_year_iid']:,.0f}. The between-district components of all three had intervals including 1; within districts over time, basic livelihood security receipt ({tci(N['bw'][BL + '__within'])}) and physical activity ({tci(N['bw'][PA + '__within'])}) were associated. In window-specific models, basic livelihood security receipt was not credible in 2011–2015 ({tci(WI(BL, 'W1_2011-15'))}) but was in 2016–2019 ({tci(WI(BL, 'W2_2016-19'))}) and 2020–2024 ({tci(WI(BL, 'W3_2020-24'))}); without 2021–2023 it remained associated ({tci(PH('drop2123', BL))}) ({sup('windows')}). With expected numbers from the resident population, basic livelihood security receipt remained associated ({tci(N['epop'][BL])}). For respiratory and gastric cancer deaths, basic livelihood security receipt and physical activity were not credible. E-values were {N['evalue'][BL]['E_point']:.2f} for basic livelihood security receipt, {N['evalue'][PA]['E_point']:.2f} for physical activity and {N['evalue'][FAC]['E_point']:.2f} for sports facilities. Posterior predictive 95% intervals covered {100*N['ppc']['coverage95']:.1f}% of observations, although the probability integral transform departed from uniformity (P = {N['ppc']['pit_ks_p']:.3f}), and 95% intervals for held-out 2024 data covered {100*N['oos']['coverage95']:.1f}% ({sup('specs')})."),
("Post hoc analyses",
 f"The share flagged as suspected pulmonary tuberculosis was not associated ({tci(PH('tb_suspect', 'ext__tb_suspect_share'))}), nor were detached-house households ({tci(PH('detached', 'detached_house_households'))}) or internal medicine specialists ({tci(PH('im_spec', 'im_specialists_per_100k'))}); with all three added, basic livelihood security receipt remained associated ({tci(PH('all3', BL))}). Unadjusted rank correlations of district standardised ratios were {D['rho_sir_tbsuspect']:.2f} with the suspected tuberculosis share and {D['rho_sir_tbhistory']:.2f} with tuberculosis history. The highest residual relative risk was in Taebaek ({N['rr_top'][0][1]:.2f}), a former coal-mining city, but the median of the seven former coal-mining districts was {N['coal_mines_med']:.2f}, against {N['coal_others_med']:.2f} elsewhere, and three of them were cold spots ({sup('posthoc')})."),
]

DISCUSSION = [
 "After standardisation for sex and age, the share of screening chest radiographs flagged as other chest disease varied between Korean districts in a spatially structured pattern that persisted over 14 years. The district markers of chest exposure examined, namely tuberculosis history, smoking, industrial land and coal-fired power plants, did not account for it, and former coal-mining areas were not consistently high. The remaining associations were small, arose within districts over time or depended on the model.",
 "### Why exposure markers did not explain the pattern",
 "If the flag mainly reflected disease, districts with more examinees under tuberculosis treatment, more smokers or more industrial land would be expected to have more flags, because radiologic changes of healed tuberculosis are associated with airflow obstruction [@hwang2014association] and smoking and occupational exposures cause chronic lung disease [@murgia2022occupational; @torn2017occupational]. Tuberculosis history and coal-fired power plants were positively associated only when district heterogeneity was ignored, and coal-fired power plants had consistently positive point estimates that were credible in the earliest window, so a modest exposure contribution cannot be excluded. The markers are crude: tuberculosis history relies on the screening questionnaire, coal-fired power plants affect few districts, and industrial land is a proxy for occupational exposure. The radiograph category also bundles findings as different as scars, nodules, pleural thickening and cardiomegaly [@pinsky2006abnormalities; @eisenberg2010low], which would dilute any single exposure. Smoking was inversely associated in some models; selective attendance or reporting by smokers is a possible explanation that these data cannot test.",
 "### Possible explanations of the geography",
 "Several explanations remain and cannot be separated here. First, unmeasured disease and exposure, such as air pollution, occupational histories, non-tuberculous mycobacterial disease or cardiac disease, may vary between districts. Second, examinee composition beyond sex and age, including the mix of employee and self-employed insured people, may differ. Third, reading and reporting thresholds may vary: readers of screening radiographs differ in how often they report nodules [@singh2012reader], and in Korea's CT lung cancer screening programme positive rates varied widely between radiologists and institutions [@hwang2021variability]. The two available markers related to reading, clinic density and the suspected tuberculosis share from the same reading, were not associated, which does not support the reading explanation, although both are indirect. The improvement in fit with province-by-year effects, the share of variance between provinces and the drift in district rankings are compatible with regional screening arrangements but are not specific to them; policy, population and coding changes at province level would produce the same signals. Facility-level data on readers, volumes and the use of computer-aided or AI reading [@kim2021performance; @li2008lung] would be needed to test the reading hypothesis.",
 "### Deprivation and physical activity",
 "Fewer flags with more basic livelihood security receipt was against the expected direction, because neighbourhood deprivation is associated with emphysema and lung function decline [@thatipelli2022neighborhood]. The association arose within districts over time, strengthened in later years, persisted without the corrected 2021–2023 values and was absent between districts and for respiratory deaths, so it describes years in which receipt rose rather than poorer districts and does not behave like a marker of chest disease burden. Changes in eligibility rules and in who attends screening [@shin2018association] are possible time-varying explanations. The credible association with fires, a negative-control exposure, suggests residual confounding or other bias if the negative-control assumption holds. More flags with more physical activity and sports facilities were not expected, as regular activity is associated with slower lung function decline in smokers [@garciaaymerich2007regular]; these associations were small, were not retained in two of four space–time models and were absent between districts, so they are not interpreted as effects.",
 "### Implications for practice",
 "For radiology practice, the findings suggest that the other chest disease flag in national screening statistics should not be read as a measure of regional chest disease burden without first examining how it is generated. Audit of flag rates by screening facility, standardised for examinee sex and age and linked to follow-up imaging and diagnoses, could show whether high-flag districts detect more disease or generate more false-positive findings, and the published district series offers a baseline against which reporting standards or AI-assisted triage [@yoo2022artificial; @kim2023multicentre] could be evaluated.",
 "### Strengths and limitations",
 "The study covered every district with complete statistics for 14 years, standardised expected numbers for sex and age within the screened population and tested the associations in many sensitivity analyses; outcome and covariate cells were checked against the published source tables. The outcome was selected for its spatial pattern from a set of screening judgements, so the existence of clustering is not an independent finding. The flag has no published definition of findings and no link to the reader, facility or follow-up, so its accuracy cannot be assessed, and examinees are assigned to districts rather than to screening facilities. Counts are examinees in each year, not unique people, and the examinee age structure was estimated from residents and national uptake; the unstable association with the share aged 80 years or older suggests that this estimate is imperfect. Hot and cold spots were defined by posterior probability alone and included most districts, so their number should not be read as a measure of effect size. The associations are ecological and cannot be transferred to individuals [@greenland2001ecologic]. Air pollution measurements and occupational histories were not available. Predictive distributions were imperfectly calibrated, and the credible negative-control exposure and small E-values show that residual confounding could explain the weaker associations.",
 "### Conclusion",
 "The share of screening chest radiographs flagged as other chest disease in Korea varies persistently between districts after sex and age are taken into account and is not explained by the district markers of tuberculosis history, smoking, industrial exposure or coal power examined. Before district flag rates are used to compare areas or plan services, facility-level audit should examine the contributions of reading and reporting practices, examinee composition and unmeasured disease.",
]

# 문장 주장 대조(결과표와 어긋나면 빌드 중단)
